public class Main {
    static <T extends Comparable<T>> T massimo(T a, T b) {
        return a.compareTo(b) >= 0 ? a : b;
    }

    static <T> void stampa(T x) {
        System.out.println("Valore: " + x);
    }

    public static void main(String[] args) {
        stampa(massimo(3, 9));
        stampa(massimo("mela", "pera"));
    }
}

