import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Function<Integer, Integer> doppio = x -> x * 2;
        Predicate<Integer> pari = x -> x % 2 == 0;
        Supplier<String> saluto = () -> "Ciao";
        Consumer<String> stampa = System.out::println;

        stampa.accept(saluto.get() + " " + doppio.apply(4));
        System.out.println(pari.negate().test(4));
        System.out.println(doppio.andThen(doppio).apply(3));
    }
}

